// Initialize A, B, C, D as in the original Polybench C code.
// All Buffers are laid out in column-major (x = column, y = row) to match the gemm.cpp style.
//
// C arrays:
//   A[ni][nk]  -> Buffer A(nk, ni)  -> A(x = k, y = i) == A[i][k]
//   B[nk][nj]  -> Buffer B(nj, nk)  -> B(x = j, y = i) == B[i][j]
//   C[nj][nm]  -> Buffer C(nm, nj)  -> C(x = k, y = i) == C[i][k]
//   D[nm][nl]  -> Buffer D(nl, nm)  -> D(x = j, y = i) == D[i][j]
static void init_array(int ni, int nj, int nk, int nl, int nm,
                       Halide::Buffer<num_t, 2> A,
                       Halide::Buffer<num_t, 2> B,
                       Halide::Buffer<num_t, 2> C,
                       Halide::Buffer<num_t, 2> D) {
    Var i("i"), j("j"), k("k");

    Func init_A("init_A"), init_B("init_B"), init_C("init_C"), init_D("init_D");

    // A[i][j] = (i*j+1) % ni / (5*ni);
    // A buffer: A(k, i) == A[i][k]
    init_A(k, i) = cast<num_t>((i * k + 1) % ni) / cast<int>(5 * ni);

    // B[i][j] = (i*(j+1)+2) % nj / (5*nj);
    // B buffer: B(j, k) == B[k][j]
    init_B(j, k) = cast<num_t>((k * (j + 1) + 2) % nj) / cast<int>(5 * nj);

    // C[i][j] = (i*(j+3) % nl) / (5*nl);
    // C buffer: C(k, i) == C[i][k]
    init_C(k, i) = cast<num_t>((i * (k + 3)) % nl) / cast<int>(5 * nl);

    // D[i][j] = ((i*(j+2)+2) % nk) / (5*nk);
    // D buffer: D(j, i) == D[i][j]
    init_D(j, i) = cast<num_t>(((i * (j + 2) + 2) % nk)) / cast<int>(5 * nk);

    // Realize into the provided Buffers.
    init_A.realize(A);
    init_B.realize(B);
    init_C.realize(C);
    init_D.realize(D);
}

int main(int argc, char *argv[]) {
    // Problem sizes from Polybench
    int ni = NI;
    int nj = NJ;
    int nk = NK;
    int nl = NL;
    int nm = NM;

    // Buffers for inputs (column-major: x = column, y = row)
    // A: NI x NK
    Halide::Buffer<num_t, 2> A(nk, ni);
    // B: NK x NJ
    Halide::Buffer<num_t, 2> B(nj, nk);
    // C: NJ x NM
    Halide::Buffer<num_t, 2> C(nm, nj);
    // D: NM x NL
    Halide::Buffer<num_t, 2> D(nl, nm);

    // Final output G: NI x NL  -> Buffer(nl, ni)
    Halide::Buffer<num_t, 2> G(nl, ni);

    // Halide ImageParams to feed A, B, C, D into the pipeline
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam D_param(type_of<num_t>(), 2, "D_param");

    // Initialize input buffers
    init_array(ni, nj, nk, nl, nm, A, B, C, D);

    // Bind ImageParams to Buffers
    A_param.set(A);
    B_param.set(B);
    C_param.set(C);
    D_param.set(D);

    // Vars and reduction domains
    Var i("i"), j("j");
    RDom r_AB(0, nk, "r_AB"); // for E = A * B (sum over nk)
    RDom r_CD(0, nm, "r_CD"); // for F = C * D (sum over nm)
    RDom r_EF(0, nj, "r_EF"); // for G = E * F (sum over nj)

    // Intermediate and final Funcs
    Func E("E"), F("F"), G_func("G_func");

    // E := A * B
    // C semantics: E[i][j] = sum_k A[i][k] * B[k][j]
    // Buffer/Func mapping: E(j, i) == E[i][j]
    E(j, i) = cast<num_t>(0);
    E(j, i) += A_param(r_AB, i) * B_param(j, r_AB);

    // F := C * D
    // C semantics: F[i][j] = sum_k C[i][k] * D[k][j]
    // Buffer/Func mapping: F(j, i) == F[i][j]
    F(j, i) = cast<num_t>(0);
    F(j, i) += C_param(r_CD, i) * D_param(j, r_CD);

    // G := E * F
    // C semantics: G[i][j] = sum_k E[i][k] * F[k][j]
    // Buffer/Func mapping: G_func(j, i) == G[i][j]
    G_func(j, i) = cast<num_t>(0);
    G_func(j, i) += E(r_EF, i) * F(j, r_EF);

    // Simple schedules that reflect row-major traversal (i outer, j inner)

    // E: initialize and then accumulate over k (nk)
    E.reorder(j, i);                  // inner j, outer i
    E.update().reorder(r_AB, j, i);   // inner r_AB, then j, then i

    // F: initialize and then accumulate over k (nm)
    F.reorder(j, i);
    F.update().reorder(r_CD, j, i);

    // G: initialize and then accumulate over k (nj)
    G_func.reorder(j, i);
    G_func.update().reorder(r_EF, j, i);

    // JIT-compile the pipeline
    G_func.compile_jit();

    // Time only the kernel execution
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: realize G_func into Buffer G
    G_func.realize(G);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the output G (row-major: i = 0..ni-1, j = 0..nl-1)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i_idx = 0; i_idx < ni; i_idx++) {
            for (int j_idx = 0; j_idx < nl; j_idx++) {
                // G buffer: G(j, i) == G[i][j] in original C
                std::cerr << G(j_idx, i_idx) << '\n';
            }
        }
    }

    // Print elapsed time in seconds
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
