        cast<num_t>(((i * (j + 2) + 2) % nk)) / cast<num_t>(5 * nk);

    init_A.realize(A);
    init_B.realize(B);
    init_C.realize(C);
    init_D.realize(D);
}

int main(int argc, char *argv[]) {
    // Problem sizes (from Polybench-style headers)
    int ni = NI;
    int nj = NJ;
    int nk = NK;
    int nl = NL;
    int nm = NM;

    // Buffers for the input matrices.
    //
    // Note: Halide uses column-major indexing (x = column, y = row).
    // For a C array M[rows][cols], we use Buffer(cols, rows) and access M(col, row).
    Halide::Buffer<num_t, 2> A(nk, ni); // A: ni x nk
    Halide::Buffer<num_t, 2> B(nj, nk); // B: nk x nj
    Halide::Buffer<num_t, 2> C(nm, nj); // C: nj x nm
    Halide::Buffer<num_t, 2> D(nl, nm); // D: nm x nl

    // Output matrix: G = (A*B)*(C*D)
    // G is ni x nl in C, so we use (nl, ni) here.
    Halide::Buffer<num_t, 2> G(nl, ni);

    // ImageParams to feed the Halide pipeline.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam D_param(type_of<num_t>(), 2, "D_param");

