    init_array(ni, nj, nk, nl, nm, A, B, C, D);

    // Bind Buffers to ImageParams.
    A_param.set(A);
    B_param.set(B);
    C_param.set(C);
    D_param.set(D);

    // ------------------------------------------------------------------
    // Halide pipeline for 3mm:
    //
    // 1) E = A * B   (ni x nk) * (nk x nj) -> (ni x nj)
    // 2) F = C * D   (nj x nm) * (nm x nl) -> (nj x nl)
    // 3) G = E * F   (ni x nj) * (nj x nl) -> (ni x nl)
    //
    // We represent all matrices as Funcs of (x = column, y = row).
    // ------------------------------------------------------------------

    Var i("i"), j("j"); // j = column, i = row

    // E(j, i) corresponds to E[i][j] in the original C code.
    Func E("E");
    {
        // Inner dimension for E: k over 0..nk-1
        RDom k_AB(0, nk, "k_AB");

        // Initialize E to 0
        E(j, i) = cast<num_t>(0);

        // E[i][j] += A[i][k] * B[k][j]
        // A(i,k) => A_param(k, i)
        // B(k,j) => B_param(j, k)
        E(j, i) += A_param(k_AB, i) * B_param(j, k_AB);
    }

    // F(j, i) corresponds to F[i][j] in the original C code.
    Func F("F");
    {
        // Inner dimension for F: k over 0..nm-1
        RDom k_CD(0, nm, "k_CD");

        // Initialize F to 0
        F(j, i) = cast<num_t>(0);

        // F[i][j] += C[i][k] * D[k][j]
        // C(i,k) => C_param(k, i)
        // D(k,j) => D_param(j, k)
        F(j, i) += C_param(k_CD, i) * D_param(j, k_CD);
    }

    // Final result: G_func(j, i) corresponds to G[i][j].
    Func G_func("G");
    {
        // Inner dimension for G: k over 0..nj-1
