        cast<num_t>((row * (col + 3) % nl)) /
        cast<int>(5 * nl);

    // D[i][j] = ((i*(j+2)+2) % nk) / (5*nk);
    // D layout: (nl, nm) -> D(col=j, row=i)
    init_D(col, row) =
        cast<num_t>((row * (col + 2) + 2) % nk) /
        cast<int>(5 * nk);

    // Realize into the provided buffers.
    init_A.realize(A);
    init_B.realize(B);
    init_C.realize(C);
    init_D.realize(D);
}

int main(int argc, char *argv[]) {
    // Problem sizes (from 3mm.hpp / defines.hpp)
    int ni = NI;
    int nj = NJ;
    int nk = NK;
    int nl = NL;
    int nm = NM;

    // Buffers: note that the first dimension is the "column" index
    // (j) and the second dimension is the "row" index (i),
    // matching the array-to-Buffer mapping rule.
    //
    // A: ni x nk  -> Buffer(nk, ni)
    // B: nk x nj  -> Buffer(nj, nk)
    // C: nj x nm  -> Buffer(nm, nj)
    // D: nm x nl  -> Buffer(nl, nm)
    // G: ni x nl  -> Buffer(nl, ni)
    Halide::Buffer<num_t, 2> A(nk, ni);
    Halide::Buffer<num_t, 2> B(nj, nk);
    Halide::Buffer<num_t, 2> C(nm, nj);
    Halide::Buffer<num_t, 2> D(nl, nm);
    Halide::Buffer<num_t, 2> G(nl, ni);

    // Initialize input matrices A, B, C, D.
    init_array(ni, nj, nk, nl, nm, A, B, C, D);

    // ImageParams for inputs
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam D_param(type_of<num_t>(), 2, "D_param");

    A_param.set(A);
    B_param.set(B);
    C_param.set(C);
    D_param.set(D);

    // Vars and reduction domains
    Var i("i"), j("j");
    RDom k1(0, A_param.dim(0).extent(), "k1"); // NK
    RDom k2(0, C_param.dim(0).extent(), "k2"); // NM
    RDom k3(0, B_param.dim(0).extent(), "k3"); // NJ

    // E := A * B
    // E has size ni x nj -> Buffer layout (nj, ni) -> E(j, i)
    Func E("E");
    E(j, i) = cast<num_t>(0);
    E(j, i) += A_param(k1, i) * B_param(j, k1);

    // F := C * D
    // F has size nj x nl -> Buffer layout (nl, nj) -> F(j, i)
    Func F("F");
    F(j, i) = cast<num_t>(0);
    F(j, i) += C_param(k2, i) * D_param(j, k2);

    // G := E * F
    // G has size ni x nl -> Buffer layout (nl, ni) -> G(j, i)
    Func G_func("G");
    G_func(j, i) = cast<num_t>(0);
    G_func(j, i) += E(k3, i) * F(j, k3);

    // Simple schedules that reflect the original loop structure.
    // Pure definitions iterate over (i, j) in row-major fashion,
    // and the reductions iterate over k innermost.
    E.reorder(j, i);
    E.update().reorder(j, k1, i);

    F.reorder(j, i);
    F.update().reorder(j, k2, i);

    G_func.reorder(j, i);
    G_func.update().reorder(j, k3, i);

    // Compute E and F fully before G, similar to the original code.
    E.compute_root();
    F.compute_root();

    // JIT compile the final stage.
    G_func.compile_jit();

    auto start = std::chrono::high_resolution_clock::now();

    // Run the pipeline: realize G into the pre-allocated buffer.
    G_func.realize(G);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the result matrix G to stderr (row-major).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nl; jj++) {
                // G[ii][jj] in C corresponds to G(jj, ii) in Halide.
                std::cerr << G(jj, ii) << '\n';
            }
        }
    }

    // Print execution time (in seconds) to stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
