using namespace Halide;

/*
 * Array initialization.
 * This mirrors the original C init_array, but uses Halide Funcs
 * to fill Halide::Buffer objects.
 */
static
void init_array(int ni, int nj, int nk, int nl, int nm,
                Halide::Buffer<num_t, 2> A,
                Halide::Buffer<num_t, 2> B,
                Halide::Buffer<num_t, 2> C,
                Halide::Buffer<num_t, 2> D) {

    Var i("i"), j("j");

    // A is NI x NK in C: A[i][j]
    // Buffer layout: A(j, i) with shape (nk, ni)
    Func init_A("init_A");
    {
        Expr num = cast<num_t>((i * j + 1) % ni);
        Expr den = cast<num_t>(5 * ni);
        init_A(j, i) = num / den;
    }

    // B is NK x NJ in C: B[i][j]
    // Buffer layout: B(j, i) with shape (nj, nk)
    Func init_B("init_B");
    {
        Expr num = cast<num_t>((i * (j + 1) + 2) % nj);
        Expr den = cast<num_t>(5 * nj);
        init_B(j, i) = num / den;
    }

    // C is NJ x NM in C: C[i][j]
    // Buffer layout: C(j, i) with shape (nm, nj)
    Func init_C("init_C");
    {
        Expr num = cast<num_t>((i * (j + 3)) % nl);
        Expr den = cast<num_t>(5 * nl);
        init_C(j, i) = num / den;
    }

    // D is NM x NL in C: D[i][j]
    // Buffer layout: D(j, i) with shape (nl, nm)
    Func init_D("init_D");
    {
        Expr num = cast<num_t>((i * (j + 2) + 2) % nk);
        Expr den = cast<num_t>(5 * nk);
        init_D(j, i) = num / den;
    }

    // Realize into the provided buffers.
    init_A.realize(A);
    init_B.realize(B);
    init_C.realize(C);
    init_D.realize(D);
}

int main(int argc, char *argv[]) {
    // Problem sizes, from Polybench macros.
    int ni = NI;
    int nj = NJ;
    int nk = NK;
    int nl = NL;
    int nm = NM;

    // Buffers corresponding to the original C arrays.
    //
    // C layout vs Halide layout (row-major C vs column-major Halide):
    //   A[NI][NK] -> Buffer A(nk, ni)  accessed as A(k, i)
    //   B[NK][NJ] -> Buffer B(nj, nk)  accessed as B(j, k)
    //   C[NJ][NM] -> Buffer C(nm, nj)  accessed as C(k, i)
    //   D[NM][NL] -> Buffer D(nl, nm)  accessed as D(j, k)
    //   E[NI][NJ] -> Buffer E(nj, ni)  accessed as E(j, i)
    //   F[NJ][NL] -> Buffer F(nl, nj)  accessed as F(j, i)
    //   G[NI][NL] -> Buffer G(nl, ni)  accessed as G(j, i)
    Buffer<num_t, 2> A(nk, ni);
    Buffer<num_t, 2> B(nj, nk);
    Buffer<num_t, 2> C(nm, nj);
    Buffer<num_t, 2> D(nl, nm);
    Buffer<num_t, 2> E(nj, ni);
    Buffer<num_t, 2> F(nl, nj);
    Buffer<num_t, 2> G(nl, ni);

    // ImageParams for the input matrices.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam D_param(type_of<num_t>(), 2, "D_param");

    // Initialize A, B, C, D.
    init_array(ni, nj, nk, nl, nm, A, B, C, D);

    // Bind ImageParams to the initialized Buffers.
    A_param.set(A);
    B_param.set(B);
    C_param.set(C);
    D_param.set(D);

    // Halide variables.
    Var i("i"), j("j");
    // Reduction domains for each of the three matrix multiplications.
    RDom rAB(0, A.dim(0).extent(), "rAB"); // k over [0, nk)
    RDom rCD(0, C.dim(0).extent(), "rCD"); // k over [0, nm)
    RDom rEF(0, B.dim(0).extent(), "rEF"); // k over [0, nj)

    // Funcs corresponding to E, F, G in the C code.
    Func E_func("E_func"), F_func("F_func"), G_func("G_func");

    // E := A * B
    //
    // C code:
    //   for i in [0, ni)
    //     for j in [0, nj)
    //       E[i][j] = 0;
    //       for k in [0, nk)
    //         E[i][j] += A[i][k] * B[k][j];
    //
    // Halide:
    //   E_func(j, i) corresponds to E[i][j].
    E_func(j, i) = cast<num_t>(0);
    E_func(j, i) += A_param(rAB, i) * B_param(j, rAB);

    // F := C * D
    //
    // C code:
    //   for i in [0, nj)
    //     for j in [0, nl)
    //       F[i][j] = 0;
    //       for k in [0, nm)
    //         F[i][j] += C[i][k] * D[k][j];
    //
    // Halide:
    //   F_func(j, i) corresponds to F[i][j].
    F_func(j, i) = cast<num_t>(0);
    F_func(j, i) += C_param(rCD, i) * D_param(j, rCD);

    // G := E * F
    //
    // C code:
    //   for i in [0, ni)
    //     for j in [0, nl)
    //       G[i][j] = 0;
    //       for k in [0, nj)
    //         G[i][j] += E[i][k] * F[k][j];
    //
    // Halide:
    //   G_func(j, i) corresponds to G[i][j].
    //   E[i][k] -> E_func(k, i)
    //   F[k][j] -> F_func(j, k)
    G_func(j, i) = cast<num_t>(0);
    G_func(j, i) += E_func(rEF, i) * F_func(j, rEF);

    // JIT-compile the pipeline.
    G_func.compile_jit();

    // Measure execution time (computation only).
    auto start = std::chrono::high_resolution_clock::now();

    // Run the kernel: realize G into its Buffer.
    G_func.realize(G);

    auto end = std::chrono::high_resolution_clock::now();
    std::chrono::duration<long double> duration(end - start);

    // Print results to stderr (to mimic the DCE behavior in Polybench).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < ni; ii++) {
            for (int jj = 0; jj < nl; jj++) {
                // G(ii, jj) in C is G(jj, ii) in Halide Buffer.
                std::cerr << G(jj, ii) << '\n';
            }
        }
    }

    // Print total time in seconds to stdout with microsecond precision.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
